    iron_booksewingbenchlight = { name = "Železni svetilo za šivalne klopi", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni svetilo za šivalne klopi za knjigoveze." },
    bronze_booksewingbenchlight = { name = "Bronast svetilo za šivalne klopi", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast svetilo za šivalne klopi za knjigoveze." },
    silver_booksewingbenchlight = { name = "Srebrn svetilo za šivalne klopi", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn svetilo za šivalne klopi za knjigoveze." },
