    jewel_set_booksewingbenchlight = { name = "Draguljast svetilo za šivalne klopi", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast svetilo za šivalne klopi za knjigoveze." },
    royal_sovereign_booksewingbenchlight = { name = "Kraljevski suveren svetilo za šivalne klopi", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren svetilo za šivalne klopi z biseri za krono." },
