    sovereign_booksewingbenchlight_palace = { name = "Suverena booksewingbenchlight palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookSewingBenchLightMaker.ironStock=14; BookSewingBenchLightMaker.bronzeStock=12; BookSewingBenchLightMaker.woodStock=12; BookSewingBenchLightMaker.leatherStock=8; BookSewingBenchLightMaker.silverStock=8; BookSewingBenchLightMaker.goldStock=6; BookSewingBenchLightMaker.jewelStock=4; BookSewingBenchLightMaker.pearlStock=4
BookSewingBenchLightMaker.productStock = {}; BookSewingBenchLightMaker.buildings = {}; BookSewingBenchLightMaker.maker = nil; BookSewingBenchLightMaker.activeMaking = {}; BookSewingBenchLightMaker.totalProducts = 0; BookSewingBenchLightMaker.dayTimer = 0
function BookSewingBenchLightMaker.init() BookSewingBenchLightMaker.ironStock=14; BookSewingBenchLightMaker.bronzeStock=12; BookSewingBenchLightMaker.woodStock=12; BookSewingBenchLightMaker.leatherStock=8; BookSewingBenchLightMaker.silverStock=8; BookSewingBenchLightMaker.goldStock=6; BookSewingBenchLightMaker.jewelStock=4; BookSewingBenchLightMaker.pearlStock=4; BookSewingBenchLightMaker.productStock={}; BookSewingBenchLightMaker.buildings={}; BookSewingBenchLightMaker.maker=nil; BookSewingBenchLightMaker.activeMaking={}; BookSewingBenchLightMaker.totalProducts=0; BookSewingBenchLightMaker.dayTimer=0; print("[BookSewingBenchLightMaker] Royal Book Sewing Bench Light Maker System initialized (6 products, 4 buildings)") end
function BookSewingBenchLightMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookSewingBenchLightMaker.maker={name=n or ("Svetilnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svetilnikar najet: %s (spretnost: %d)",BookSewingBenchLightMaker.maker.name,s),"success") end; return true end
function BookSewingBenchLightMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookSewingBenchLightMaker.build(id) local ok,e=BookSewingBenchLightMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookSewingBenchLightMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookSewingBenchLightMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookSewingBenchLightMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookSewingBenchLightMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookSewingBenchLightMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookSewingBenchLightMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookSewingBenchLightMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookSewingBenchLightMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookSewingBenchLightMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookSewingBenchLightMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookSewingBenchLightMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookSewingBenchLightMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookSewingBenchLightMaker.buildings==0 then return false,"Potrebna svetilna delavnica" end; if not BookSewingBenchLightMaker.maker then return false,"Potreben svetilnikar" end; return true end
function BookSewingBenchLightMaker.make(pt,qty) qty=qty or 1; local ok,e=BookSewingBenchLightMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookSewingBenchLightMaker.ironStock=BookSewingBenchLightMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookSewingBenchLightMaker.bronzeStock=BookSewingBenchLightMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookSewingBenchLightMaker.woodStock=BookSewingBenchLightMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookSewingBenchLightMaker.leatherStock=BookSewingBenchLightMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookSewingBenchLightMaker.silverStock=BookSewingBenchLightMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookSewingBenchLightMaker.goldStock=BookSewingBenchLightMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookSewingBenchLightMaker.jewelStock=BookSewingBenchLightMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookSewingBenchLightMaker.pearlStock=BookSewingBenchLightMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookSewingBenchLightMaker.maker then t=math.max(1,t-math.floor(BookSewingBenchLightMaker.maker.skill/13)) end; table.insert(BookSewingBenchLightMaker.activeMaking,{id="booksewingbenchlight_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookSewingBenchLightMaker.completeMaking(m) local q=1.0+(BookSewingBenchLightMaker.getQualityBonus()/100); if BookSewingBenchLightMaker.maker then q=q+(BookSewingBenchLightMaker.maker.skill/140) end; q=math.min(2.5,q); BookSewingBenchLightMaker.productStock[m.productType]=(BookSewingBenchLightMaker.productStock[m.productType] or 0)+m.quantity; BookSewingBenchLightMaker.totalProducts=BookSewingBenchLightMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookSewingBenchLightMaker.maker then BookSewingBenchLightMaker.maker.itemsMade=BookSewingBenchLightMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookSewingBenchLightMaker.maker.skill=math.min(100,BookSewingBenchLightMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Svetilo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"booksewingbenchlight.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookSewingBenchLightMaker.update(dt) if not _G.state then return end; BookSewingBenchLightMaker.dayTimer=BookSewingBenchLightMaker.dayTimer+dt; if BookSewingBenchLightMaker.dayTimer>=30 then BookSewingBenchLightMaker.dayTimer=0; for i=#BookSewingBenchLightMaker.activeMaking,1,-1 do local m=BookSewingBenchLightMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookSewingBenchLightMaker.completeMaking(m); table.remove(BookSewingBenchLightMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookSewingBenchLightMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookSewingBenchLightMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookSewingBenchLightMaker.getStats() return {ironStock=BookSewingBenchLightMaker.ironStock,bronzeStock=BookSewingBenchLightMaker.bronzeStock,woodStock=BookSewingBenchLightMaker.woodStock,leatherStock=BookSewingBenchLightMaker.leatherStock,silverStock=BookSewingBenchLightMaker.silverStock,goldStock=BookSewingBenchLightMaker.goldStock,jewelStock=BookSewingBenchLightMaker.jewelStock,pearlStock=BookSewingBenchLightMaker.pearlStock,productStock=BookSewingBenchLightMaker.productStock,numBuildings=#BookSewingBenchLightMaker.buildings,hasMaker=BookSewingBenchLightMaker.maker~=nil,makerName=BookSewingBenchLightMaker.maker and BookSewingBenchLightMaker.maker.name or "—",makerSkill=BookSewingBenchLightMaker.maker and BookSewingBenchLightMaker.maker.skill or 0,activeMaking=#BookSewingBenchLightMaker.activeMaking,totalProducts=BookSewingBenchLightMaker.totalProducts} end
return BookSewingBenchLightMaker
